const listParcels = `-- name: ListParcels :many
SELECT p.id, p.tracking_number, p.status, p.sender_name, p.sender_phone, p.recipient_name, p.recipient_phone,
       p.category, p.weight_kg, p.pieces, p.price, p.payer, p.paid_at, p.created_at, p.departure_id,
       oa.name AS origin_agency_name, da.name AS destination_agency_name, ca.name AS current_agency_name
FROM parcels p
JOIN agencies oa ON oa.id = p.origin_agency_id
JOIN agencies da ON da.id = p.destination_agency_id
LEFT JOIN agencies ca ON ca.id = p.current_agency_id
WHERE p.company_id = $1
  AND ($2::text IS NULL OR p.status = $2::text)
  AND ($3::uuid IS NULL OR p.current_agency_id = $3::uuid
       OR p.origin_agency_id = $3::uuid OR p.destination_agency_id = $3::uuid)
  AND ($4::text IS NULL OR p.tracking_number ILIKE '%' || $4::text || '%'
       OR p.sender_phone LIKE '%' || $4::text || '%' OR p.recipient_phone LIKE '%' || $4::text || '%'
       OR p.recipient_name ILIKE '%' || $4::text || '%' OR p.sender_name ILIKE '%' || $4::text || '%')
ORDER BY p.created_at DESC
LIMIT $6 OFFSET $5
`

type ListParcelsParams struct {
	CompanyID uuid.UUID
	Status    *string
	AgencyID  *uuid.UUID
	Search    *string
	Off       int32
	Lim       int32
}

type ListParcelsRow struct {
	ID                    uuid.UUID
	TrackingNumber        string
	Status                string
	SenderName            string
	SenderPhone           string
	RecipientName         string
	RecipientPhone        string
	Category              string
	WeightKg              float64
	Pieces                int32
	Price                 int64
	Payer                 string
	PaidAt                *time.Time
	CreatedAt             time.Time
	DepartureID           *uuid.UUID
	OriginAgencyName      string
	DestinationAgencyName string
	CurrentAgencyName     *string
}

func (q *Queries) ListParcels(ctx context.Context, arg ListParcelsParams) ([]ListParcelsRow, error) {
	rows, err := q.db.Query(ctx, listParcels,
		arg.CompanyID,
		arg.Status,
		arg.AgencyID,
		arg.Search,
		arg.Off,
		arg.Lim,
	)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []ListParcelsRow{}
	for rows.Next() {
		var i ListParcelsRow
		if err := rows.Scan(
			&i.ID,
			&i.TrackingNumber,
			&i.Status,
			&i.SenderName,
			&i.SenderPhone,
			&i.RecipientName,
			&i.RecipientPhone,
			&i.Category,
			&i.WeightKg,
			&i.Pieces,
			&i.Price,
			&i.Payer,
			&i.PaidAt,
			&i.CreatedAt,
			&i.DepartureID,
			&i.OriginAgencyName,
			&i.DestinationAgencyName,
			&i.CurrentAgencyName,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

